//! Golden decode-regression vectors (Task 8, decision 9c).
//!
//! Reads every WAV + `testdata/golden/manifest.toml` (generated by
//! `cargo run -p coppa-bench --release --example golden_vectors_gen`,
//! `crates/coppa-bench/diagnostics/golden_vectors_gen.rs`) and asserts that
//! the receivers recover each manifest entry's exact payload. Since COP-129
//! the corpus covers every speed level (1-8 on four channels, 9 on `clean` and
//! `awgn12`), multi-codeword frames and retransmissions. Single-frame entries
//! go through both `CoppaTransceiver::receive` and `StreamingReceiver`;
//! retransmission entries (`rv_sequence` with more than one element) hold two
//! frames and go through `StreamingReceiver` only, because the batch call is
//! single-frame by design. A future PHY/FEC change that silently breaks
//! decoding of one of these frozen, committed frames now fails a real,
//! visible test -- not just a full bench sweep nobody runs by default.
//!
//! ## Why this file lives here
//!
//! The task brief names `crates/coppa-protocol/tests/golden_vectors.rs`
//! explicitly, matching Cargo's standard per-crate integration-test
//! convention (any `.rs` directly under a crate's own `tests/` directory
//! becomes its own integration-test binary, run via
//! `cargo test -p coppa-protocol --test golden_vectors` or as part of
//! `cargo test --workspace`) -- this crate didn't have a `tests/` directory
//! before this task; this is the first file in it. This repo's OTHER
//! integration tests (`tests/phase_c_loopback.rs` etc.) instead live under
//! the repo-root `coppa` package's own `tests/` directory, because those
//! predate this task and exercise multiple crates' interaction generically;
//! this test is scoped tightly to `coppa-protocol`'s own `CoppaTransceiver`
//! decode path, so a per-crate `tests/` directory (Cargo's default
//! convention, not a repo-specific one) fits at least as well and is what
//! the brief asked for.

use std::path::{Path, PathBuf};

use coppa_bench::scenario::select_profile;
use coppa_codec::ofdm::CoppaProfile;
use coppa_protocol::modem::streaming::{DecodedFrame, StreamingReceiver};
use coppa_protocol::modem::transceiver::CoppaTransceiver;

#[derive(serde::Deserialize)]
struct ManifestFile {
    vectors: Vec<VectorEntry>,
}

#[derive(serde::Deserialize)]
struct VectorEntry {
    id: String,
    level: u8,
    channel: String,
    #[allow(dead_code)]
    seed: u64,
    #[allow(dead_code)]
    seed_attempts: u64,
    /// LDPC codewords in the frame (COP-129). Absent means 1.
    #[serde(default = "one")]
    codewords: u8,
    /// RV of each frame in the WAV, in on-air order (COP-129). Absent or empty
    /// means one RV0 frame.
    #[serde(default)]
    rv_sequence: Vec<u8>,
    payload_hex: String,
    wav_file: String,
    sample_rate: u32,
    expected_decode_ok: bool,
}

fn one() -> u8 {
    1
}

impl VectorEntry {
    /// More than one frame: the WAV is a retransmission sequence.
    fn is_retransmission(&self) -> bool {
        self.rv_sequence.len() > 1
    }

    /// RV of the frame that should decode: the last one on air.
    fn last_rv(&self) -> u8 {
        self.rv_sequence.last().copied().unwrap_or(0)
    }
}

fn read_manifest() -> ManifestFile {
    let manifest_text = std::fs::read_to_string(golden_dir().join("manifest.toml"))
        .expect("failed to read golden manifest.toml");
    toml::from_str(&manifest_text).expect("failed to parse golden manifest.toml")
}

/// Golden-vector root directory, relative to this crate's own manifest dir.
fn golden_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/golden")
}

/// Mirrors `golden_vectors_gen.rs`'s `profile_for`: every level uses its normal
/// per-level routing (delegated to `coppa_bench::scenario::select_profile`, the
/// single source of truth for that rule -- levels 1-4 -> hf_standard, 5+ ->
/// vhf_wide) EXCEPT the `poor25` and `ssbcfo` channel conditions, which force
/// `hf_standard` for every level (an HF-multipath Watterson channel is not a
/// fair test of the VHF-routed profile's much shorter cyclic prefix, and the
/// SSB rig passband filter is an HF-specific impairment not applicable to the
/// VHF-routed profile's wider active band -- see that generator's module doc).
///
/// This pulls in `coppa-bench` as a dev-dependency of `coppa-protocol`, which
/// looks like it should be a cycle (`coppa-bench` depends on `coppa-protocol`
/// as a normal dependency) but isn't: Cargo resolves dev-dependency edges
/// separately from the normal dependency graph, since they're only needed to
/// build this crate's own tests/examples, not to build `coppa-protocol` itself
/// as a library -- verified directly (`cargo check -p coppa-protocol --tests`
/// and `cargo tree -p coppa-protocol -e dev` both resolve cleanly here).
fn profile_for(level: u8, channel: &str) -> CoppaProfile {
    if channel == "poor25" || channel == "ssbcfo" {
        return CoppaProfile::hf_standard();
    }
    select_profile(level)
}

fn decode_hex(s: &str) -> Vec<u8> {
    assert!(s.len() % 2 == 0, "odd-length hex string: {s}");
    (0..s.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&s[i..i + 2], 16).unwrap_or_else(|e| panic!("bad hex in {s}: {e}"))
        })
        .collect()
}

fn read_wav_f32(path: &Path) -> (Vec<f32>, u32) {
    let mut reader = hound::WavReader::open(path)
        .unwrap_or_else(|e| panic!("failed to open golden WAV {}: {e}", path.display()));
    let spec = reader.spec();
    assert_eq!(
        spec.bits_per_sample,
        16,
        "golden WAV {} is not 16-bit PCM",
        path.display()
    );
    assert_eq!(
        spec.sample_format,
        hound::SampleFormat::Int,
        "golden WAV {} is not integer PCM",
        path.display()
    );
    // Full-scale normalization, matching `coppa_audio::file_backend::WavSource::open`'s
    // `1i64 << (bits_per_sample - 1)` convention (32768 for 16-bit), not `i16::MAX` (32767).
    // The two differ only by a ~1/32768 amplitude scale -- not a correctness bug on its own
    // (this reader and `golden_vectors_gen.rs`'s writer were self-consistent either way), but
    // an unnecessary, undocumented divergence from house style.
    let max_val = (1i64 << (spec.bits_per_sample - 1)) as f32;
    let samples: Vec<f32> = reader
        .samples::<i16>()
        .map(|s| {
            s.unwrap_or_else(|e| panic!("bad sample in {}: {e}", path.display())) as f32 / max_val
        })
        .collect();
    (samples, spec.sample_rate)
}

#[test]
fn golden_vectors_decode_to_expected_payloads() {
    let dir = golden_dir();
    let manifest_path = dir.join("manifest.toml");
    let manifest_text = std::fs::read_to_string(&manifest_path).unwrap_or_else(|e| {
        panic!(
            "failed to read golden manifest {}: {e} (run `cargo run -p coppa-bench --release \
             --example golden_vectors_gen` from the workspace root to (re)generate it)",
            manifest_path.display()
        )
    });
    let manifest: ManifestFile =
        toml::from_str(&manifest_text).expect("failed to parse golden manifest.toml");

    assert!(
        !manifest.vectors.is_empty(),
        "golden manifest has no vectors"
    );

    let mut failures = Vec::new();

    for v in &manifest.vectors {
        if v.is_retransmission() {
            // Batch `receive` decodes one frame by design and never sees the
            // earlier transmission it must combine with. The streaming test
            // below covers these entries.
            continue;
        }
        let wav_path = dir.join(&v.wav_file);
        let (samples, sample_rate) = read_wav_f32(&wav_path);
        if sample_rate != v.sample_rate {
            failures.push(format!(
                "{}: sample rate mismatch (wav={sample_rate}, manifest={})",
                v.id, v.sample_rate
            ));
            continue;
        }

        let expected_payload = decode_hex(&v.payload_hex);
        let profile = profile_for(v.level, &v.channel);
        let tx = CoppaTransceiver::new(profile, 1);

        match tx.receive(&samples) {
            Ok((header, bytes, _rec_level)) => {
                if !v.expected_decode_ok {
                    failures.push(format!(
                        "{}: decoded successfully but manifest expected a decode failure",
                        v.id
                    ));
                    continue;
                }
                if header.speed_level != v.level {
                    failures.push(format!(
                        "{}: decoded header speed_level {} != manifest level {}",
                        v.id, header.speed_level, v.level
                    ));
                }
                if header.codewords != v.codewords {
                    failures.push(format!(
                        "{}: decoded header codewords {} != manifest codewords {}",
                        v.id, header.codewords, v.codewords
                    ));
                }
                if bytes != expected_payload {
                    failures.push(format!(
                        "{}: recovered payload does not match manifest (recovered {} bytes, expected {})",
                        v.id,
                        bytes.len(),
                        expected_payload.len()
                    ));
                }
            }
            Err(e) => {
                if v.expected_decode_ok {
                    failures.push(format!("{}: expected clean decode but got {e:?}", v.id));
                }
            }
        }
    }

    assert!(
        failures.is_empty(),
        "golden vector failures ({}/{}):\n{}",
        failures.len(),
        manifest.vectors.len(),
        failures.join("\n")
    );
}

/// Multi-codeword ids the corpus must hold, with their codeword counts.
const MULTI_CODEWORD_VECTORS: &[(&str, u8)] = &[
    ("L4_awgn12_cw3", 3),
    ("L7_awgn12_cw3", 3),
    ("L9_awgn12_cw8", 8),
];

/// Retransmission ids the corpus must hold, with their RV sequences.
const RETRANSMISSION_VECTORS: &[(&str, &[u8])] = &[
    ("L9_awgn12_rtx_rv1", &[0, 1]),
    ("L9_awgn12_rtx_rv2", &[0, 2]),
    ("L9_awgn12_rtx_rv3", &[0, 3]),
    ("L9_awgn12_rtx_rv0", &[0, 0]),
    ("L4_awgn12_rtx_rv2", &[0, 2]),
];

/// Sanity check: the manifest covers the whole declared corpus (COP-129), not
/// a partial set some generator run happened to produce: levels 1-8 x
/// channels {clean, awgn12, poor25, ssbcfo}, level 9 on {clean, awgn12} only
/// (VHF-only, ADR-009), the multi-codeword entries and the retransmission
/// entries.
#[test]
fn golden_manifest_covers_the_full_grid() {
    let manifest = read_manifest();
    let channels = ["clean", "awgn12", "poor25", "ssbcfo"];
    let single = |v: &&VectorEntry| v.codewords == 1 && !v.is_retransmission();

    for level in 1u8..=8 {
        for &channel in &channels {
            assert!(
                manifest
                    .vectors
                    .iter()
                    .filter(single)
                    .any(|v| v.level == level && v.channel == channel),
                "missing single-frame golden vector for level {level} / channel {channel}"
            );
        }
    }
    for channel in ["clean", "awgn12"] {
        assert!(
            manifest
                .vectors
                .iter()
                .filter(single)
                .any(|v| v.level == 9 && v.channel == channel),
            "missing single-frame golden vector for level 9 / channel {channel}"
        );
    }
    for channel in ["poor25", "ssbcfo"] {
        assert!(
            !manifest
                .vectors
                .iter()
                .any(|v| v.level == 9 && v.channel == channel),
            "level 9 is VHF-only (ADR-009) and must have no {channel} vector"
        );
    }

    let find = |id: &str| {
        manifest
            .vectors
            .iter()
            .find(|v| v.id == id)
            .unwrap_or_else(|| panic!("missing golden vector {id}"))
    };

    for &(id, codewords) in MULTI_CODEWORD_VECTORS {
        let v = find(id);
        assert_eq!(v.codewords, codewords, "{id}: codewords");
        let len = v.payload_hex.len() / 2;
        assert!(
            len % codewords as usize != 0,
            "{id}: payload length {len} must not split evenly over {codewords} codewords \
             (SPEC §9.1's +1 rule)"
        );
    }
    // One multi-codeword entry on each side of the cross-codeword interleave
    // gate (`CROSS_CODEWORD_INTERLEAVE_MIN_LEVEL` = 5, SPEC §9.3).
    let multi_levels: Vec<u8> = MULTI_CODEWORD_VECTORS
        .iter()
        .map(|&(id, _)| find(id).level)
        .collect();
    assert!(
        multi_levels.iter().any(|&l| l < 5) && multi_levels.iter().any(|&l| l >= 5),
        "multi-codeword entries must sit on both sides of level 5, got {multi_levels:?}"
    );

    let mut rvs_covered = [false; 4];
    for &(id, rv_sequence) in RETRANSMISSION_VECTORS {
        let v = find(id);
        assert_eq!(v.rv_sequence, rv_sequence, "{id}: rv_sequence");
        for &rv in rv_sequence {
            rvs_covered[rv as usize] = true;
        }
    }
    assert_eq!(
        rvs_covered, [true; 4],
        "retransmission entries must cover RV 0, 1, 2 and 3"
    );

    let mut ids = std::collections::HashSet::new();
    for v in &manifest.vectors {
        assert!(
            ids.insert(v.id.as_str()),
            "duplicate golden vector id {}",
            v.id
        );
    }
    assert_eq!(
        manifest.vectors.len(),
        8 * channels.len() + 2 + MULTI_CODEWORD_VECTORS.len() + RETRANSMISSION_VECTORS.len(),
        "manifest has unexpected extra/missing entries"
    );
}

/// Streaming chunk size: 100 ms at 48 kHz, the size `coppa rx` and the
/// daemon's audio loop push.
const STREAM_CHUNK: usize = 4800;
/// Trailing zeros after each WAV, matching the CLI's `TRAILING_FLUSH_SAMPLES`,
/// so a frame that ends near the end of the file still completes.
const TRAILING_FLUSH_SAMPLES: usize = 8192;
/// Silence before, between and after the frames of a retransmission WAV
/// (100 ms at 48 kHz, SPEC §14).
const RTX_GAP_SAMPLES: usize = 4800;

/// Decode `samples` through a fresh `StreamingReceiver`, in `STREAM_CHUNK`
/// pushes followed by `TRAILING_FLUSH_SAMPLES` zeros.
fn stream_decode(v: &VectorEntry, samples: &[f32]) -> Vec<DecodedFrame> {
    let mut buf = samples.to_vec();
    buf.extend(std::iter::repeat_n(0.0f32, TRAILING_FLUSH_SAMPLES));
    let mut rx = StreamingReceiver::new(profile_for(v.level, &v.channel), 1);
    let mut decoded = Vec::new();
    for chunk in buf.chunks(STREAM_CHUNK) {
        decoded.extend(rx.push_samples(chunk));
    }
    decoded
}

/// End of the first frame's trailing gap in a retransmission WAV. Every frame
/// has the same level and codeword count, so the same length:
/// `len = (n + 1) * gap + n * frame_len`.
fn first_frame_end(v: &VectorEntry, len: usize) -> Option<usize> {
    let n = v.rv_sequence.len();
    let frames = len.checked_sub((n + 1) * RTX_GAP_SAMPLES)?;
    (frames % n == 0).then(|| RTX_GAP_SAMPLES + frames / n + RTX_GAP_SAMPLES)
}

/// COP-126: every golden vector decodes through `StreamingReceiver`, the
/// receive path the daemon, `coppa rx` and the FFI share, not only through
/// the batch `CoppaTransceiver::receive` above. Before COP-126 the streaming
/// detector saw unfiltered noise and missed `L1_awgn12` and `L2_awgn12`.
///
/// COP-129: each WAV must give exactly one frame with the exact payload and
/// codeword count. For a retransmission entry that frame must carry the last
/// RV in `rv_sequence`, and the WAV cut after the first frame's trailing gap
/// must give no frame at all, which proves the receiver combined the two
/// transmissions (a lone RV1-RV3 frame does not decode at L4 or L9 either).
#[test]
fn golden_vectors_decode_through_the_streaming_receiver() {
    let dir = golden_dir();
    let manifest = read_manifest();
    assert!(
        !manifest.vectors.is_empty(),
        "golden manifest has no vectors"
    );

    let mut failures = Vec::new();
    for v in &manifest.vectors {
        let (samples, _) = read_wav_f32(&dir.join(&v.wav_file));
        let expected_payload = decode_hex(&v.payload_hex);

        if v.is_retransmission() {
            // The first frame alone must give nothing, so the one frame the
            // whole WAV gives can only come from combining. This is what makes
            // the Chase entry (RV0 then RV0) meaningful.
            match first_frame_end(v, samples.len()) {
                None => {
                    failures.push(format!(
                        "{}: {} samples do not fit the SPEC §14 retransmission layout",
                        v.id,
                        samples.len()
                    ));
                    continue;
                }
                Some(end) => {
                    let alone = stream_decode(v, &samples[..end]);
                    if !alone.is_empty() {
                        failures.push(format!(
                            "{}: the first frame alone decoded {} frame(s); \
                             the vector no longer tests combining",
                            v.id,
                            alone.len()
                        ));
                        continue;
                    }
                }
            }
        }

        let decoded = stream_decode(v, &samples);
        let ok = decoded.len() == 1
            && decoded[0].payload == expected_payload
            && decoded[0].header.speed_level == v.level
            && decoded[0].header.codewords == v.codewords
            && (!v.is_retransmission() || decoded[0].header.fec_type & 0x03 == v.last_rv());
        if ok != v.expected_decode_ok {
            let detail: Vec<String> = decoded
                .iter()
                .map(|f| {
                    format!(
                        "[{} bytes, level {}, codewords {}, rv {}]",
                        f.payload.len(),
                        f.header.speed_level,
                        f.header.codewords,
                        f.header.fec_type & 0x03
                    )
                })
                .collect();
            failures.push(format!(
                "{}: {} frame(s) decoded through the streaming receiver {}",
                v.id,
                decoded.len(),
                detail.join(" ")
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "streaming golden vector failures ({}/{}):\n{}",
        failures.len(),
        manifest.vectors.len(),
        failures.join("\n")
    );
}
